PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX saref: <https://w3id.org/saref#>

SELECT ?device ?lightPoint ?direction ?color ?transmissionPeriod ?projectedFromHeight
WHERE {
  ?device s4envi:projectsLight ?lightPoint .
  ?lightPoint s4envi:isProjectedInDirection ?direction .
  OPTIONAL { ?lightPoint s4envi:hasColor ?color . }
  OPTIONAL { ?lightPoint s4envi:hasTransmissionPeriod ?transmissionPeriod . }
  OPTIONAL { ?lightPoint s4envi:isProjectedFromHeight ?projectedFromHeight . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX saref: <https://w3id.org/saref#>

SELECT ?device ?component ?property ?relation
WHERE {
  ?device s4envi:hasComponent ?component .
  OPTIONAL { ?component s4envi:hasGeometry ?geometry . }
  OPTIONAL { ?component s4envi:hasColor ?color . }
  OPTIONAL { ?component s4envi:isConnectedTo ?connectedTo . }
  OPTIONAL { ?component s4envi:encapsulates ?encapsulates . }
  OPTIONAL { ?component s4envi:projectsLight ?projectsLight . }
  OPTIONAL { ?component s4envi:isAccesibleThrough ?accessibleThrough . }
  OPTIONAL { ?component s4envi:contains ?contains . }
  OPTIONAL { ?component s4envi:isProjectedInDirection ?projectedDirection . }
  OPTIONAL { ?component s4envi:hasTransmissionPeriod ?transmissionPeriod . }
  OPTIONAL { ?component s4envi:isProjectedFromHeight ?projectedHeight . }
  OPTIONAL { ?component s4envi:hasLightPoint ?lightPoint . }
  OPTIONAL { ?component s4envi:usesCommunicationProtocol ?communicationProtocol . }
  OPTIONAL { ?component s4envi:hasFrequencyMeasurement ?frequencyMeasurement . }
  OPTIONAL { ?component s4envi:isContainedIn ?containedIn . }
  OPTIONAL { ?component s4envi:usesCommunicationInterface ?communicationInterface . }
  OPTIONAL { ?component s4envi:affectsProperty ?affectsProperty . }
  OPTIONAL { ?component saref:measuresProperty ?measuredProperty . }
  OPTIONAL { ?component saref:makesMeasurement ?measurement . }
  OPTIONAL { ?component saref:isMeasuredIn ?unit . }
  OPTIONAL { ?component saref:relatesToProperty ?relatedProperty . }

  BIND(?geometry AS ?property)
  BIND(?color AS ?property)
  BIND(?connectedTo AS ?relation)
  BIND(?encapsulates AS ?relation)
  BIND(?projectsLight AS ?relation)
  BIND(?accessibleThrough AS ?relation)
  BIND(?contains AS ?relation)
  BIND(?projectedDirection AS ?relation)
  BIND(?transmissionPeriod AS ?relation)
  BIND(?projectedHeight AS ?relation)
  BIND(?lightPoint AS ?relation)
  BIND(?communicationProtocol AS ?relation)
  BIND(?frequencyMeasurement AS ?relation)
  BIND(?containedIn AS ?relation)
  BIND(?communicationInterface AS ?relation)
  BIND(?affectsProperty AS ?relation)
  BIND(?measuredProperty AS ?property)
  BIND(?measurement AS ?property)
  BIND(?unit AS ?property)
  BIND(?relatedProperty AS ?property)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX saref: <https://w3id.org/saref#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?device ?system ?property ?component
WHERE {
  ?device s4envi:isComponentOf ?system .
  OPTIONAL { ?system s4envi:hasComponent ?component . }
  OPTIONAL { ?system saref:measuresProperty ?property . }
  OPTIONAL { ?system s4envi:hasGeometry ?geometry . }
  OPTIONAL { ?system s4envi:hasColor ?color . }
  OPTIONAL { ?system s4envi:encapsulates ?encapsulation . }
  OPTIONAL { ?system s4envi:projectsLight ?lightProjection . }
  OPTIONAL { ?system s4envi:isAccesibleThrough ?accessPoint . }
  OPTIONAL { ?system s4envi:contains ?containedElement . }
  OPTIONAL { ?system s4envi:isConnectedTo ?connectedDevice . }
  OPTIONAL { ?system s4envi:usesCommunicationProtocol ?protocol . }
  OPTIONAL { ?system s4envi:usesCommunicationInterface ?interface . }
  OPTIONAL { ?system s4envi:hasFrequencyMeasurement ?frequency . }
  OPTIONAL { ?system s4envi:hasTransmissionPeriod ?transmissionPeriod . }
  OPTIONAL { ?system s4envi:isProjectedInDirection ?direction . }
  OPTIONAL { ?system s4envi:isProjectedFromHeight ?height . }
  OPTIONAL { ?system s4envi:hasLightPoint ?lightPoint . }
  OPTIONAL { ?system s4envi:isContainedIn ?container . }
  OPTIONAL { ?system s4envi:affectsProperty ?affectedProperty . }
}

