PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?frequencyMeasurement ?periodMeasurement ?heightMeasurement ?device
WHERE {
  {
    ?frequencyMeasurement a s4envi:FrequencyMeasurement .
    ?device a s4envi:Device ;
            saref:isMeasuredBy ?frequencyMeasurement .
  }
  UNION
  {
    ?periodMeasurement a s4envi:PeriodMeasurement .
    ?device a s4envi:Device ;
            saref:isMeasuredBy ?periodMeasurement .
  }
  UNION
  {
    ?heightMeasurement a s4envi:HeightMeasurement .
    ?device a s4envi:Device ;
            saref:isMeasuredBy ?heightMeasurement .
  }
}

