  wgs84:Point rdfs:isDefinedBy ?definition
}

PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?pointType ?characteristic
WHERE {
  ?pointType rdfs:subClassOf* wgs84:Point .
  OPTIONAL {
    ?pointType rdfs:isDefinedBy ?characteristic
  }
  FILTER (strstarts(str(?pointType), "http://www.w3.org/2003/01/geo/wgs84_pos#") || strstarts(str(?pointType), "http://example.org/s4envi#"))
}

PREFIX wgs84: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?subclass (GROUP_CONCAT(DISTINCT ?difference; separator=", ") AS ?differences)
WHERE {
  ?subclass rdfs:subClassOf wgs84:Point .
  FILTER(?subclass != s4envi:LightPoint)
  OPTIONAL {
    ?subclass rdfs:subClassOf ?superclass .
    FILTER(?superclass != wgs84:Point)
    BIND(CONCAT("Subclass of ", STR(?superclass)) AS ?difference)
  }
  OPTIONAL {
    ?subclass rdfs:isDefinedBy ?definition .
    BIND(CONCAT("Defined by ", STR(?definition)) AS ?difference)
  }
  OPTIONAL {
    ?subclass rdf:type ?type .
    FILTER(?type != owl:Class)
    BIND(CONCAT("Type: ", STR(?type)) AS ?difference)
  }
  BIND(IF(BOUND(?difference), ?difference, "") AS ?difference)
}
GROUP BY ?subclass
